-- Hand-written: Atlas reverses a SQLite table rebuild by dropping the new_* temp table, which no longer exists on the way down.
PRAGMA foreign_keys = off;
-- 'upgrades' has no old equivalent and folds to false: replace_existing = true replaced every file, which would delete files the release does not beat.
CREATE TABLE `new_download_records` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `create_time` datetime NOT NULL, `update_time` datetime NOT NULL, `title` text NOT NULL, `quality` text NULL, `size` integer NULL, `status` text NOT NULL DEFAULT ('downloading'), `torrent_hash` text NULL, `release_group` text NULL, `save_path` text NULL, `import_attempts` integer NOT NULL DEFAULT (0), `failure_reason` text NULL, `imported_at` datetime NULL, `indexer_name` text NULL, `download_client_name` text NULL, `replace_existing` bool NOT NULL DEFAULT (false), `hold_reasons` json NULL, `verification_bypassed` bool NOT NULL DEFAULT (false), `episode_download_records` integer NULL, `movie_download_records` integer NULL, CONSTRAINT `download_records_episodes_download_records` FOREIGN KEY (`episode_download_records`) REFERENCES `episodes` (`id`) ON DELETE CASCADE, CONSTRAINT `download_records_movies_download_records` FOREIGN KEY (`movie_download_records`) REFERENCES `movies` (`id`) ON DELETE CASCADE);
INSERT INTO `new_download_records` (`id`, `create_time`, `update_time`, `title`, `quality`, `size`, `status`, `torrent_hash`, `release_group`, `save_path`, `import_attempts`, `failure_reason`, `imported_at`, `indexer_name`, `download_client_name`, `replace_existing`, `hold_reasons`, `verification_bypassed`, `episode_download_records`, `movie_download_records`) SELECT `id`, `create_time`, `update_time`, `title`, `quality`, `size`, `status`, `torrent_hash`, `release_group`, `save_path`, `import_attempts`, `failure_reason`, `imported_at`, `indexer_name`, `download_client_name`, `replace_mode` = 'all', `hold_reasons`, `verification_bypassed`, `episode_download_records`, `movie_download_records` FROM `download_records`;
DROP TABLE `download_records`;
ALTER TABLE `new_download_records` RENAME TO `download_records`;
PRAGMA foreign_keys = on;
